-- compatibility: incremental
-- Reviewed stable identity and immutable, complete cross-period residual import.
CREATE TABLE ledger_bank_identities(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id),firm_id TEXT NOT NULL,company_id TEXT NOT NULL,ledger_id TEXT NOT NULL REFERENCES ledgers(id),name TEXT NOT NULL,reason TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE bank_identity_bindings(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id),firm_id TEXT NOT NULL,company_id TEXT NOT NULL,ledger_id TEXT NOT NULL REFERENCES ledgers(id),bank_account_id TEXT NOT NULL REFERENCES bank_accounts(id),stable_bank_id TEXT NOT NULL REFERENCES ledger_bank_identities(id),idempotency_key TEXT NOT NULL,request_fingerprint TEXT NOT NULL,reason TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(book_id,idempotency_key));
CREATE TABLE bank_identity_reviews(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id),firm_id TEXT NOT NULL,company_id TEXT NOT NULL,binding_id TEXT NOT NULL UNIQUE REFERENCES bank_identity_bindings(id),decision TEXT NOT NULL CHECK(decision IN('approved','rejected')),reason TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE subledger_period_bridges(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id),firm_id TEXT NOT NULL,company_id TEXT NOT NULL,ledger_id TEXT NOT NULL REFERENCES ledgers(id),source_book_id TEXT NOT NULL REFERENCES books(id),source_lock_id TEXT NOT NULL REFERENCES internal_period_locks(id),source_binding_id TEXT NOT NULL REFERENCES opening_bindings(id),target_binding_id TEXT NOT NULL REFERENCES opening_bindings(id),idempotency_key TEXT NOT NULL,request_fingerprint TEXT NOT NULL,reason TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(book_id));
CREATE TABLE subledger_bridge_items(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id),firm_id TEXT NOT NULL,company_id TEXT NOT NULL,bridge_id TEXT NOT NULL REFERENCES subledger_period_bridges(id),source_item_id TEXT NOT NULL REFERENCES subledger_items(id),target_item_id TEXT NOT NULL UNIQUE REFERENCES subledger_items(id),remaining_cents BIGINT NOT NULL CHECK(remaining_cents>0),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(bridge_id,source_item_id));
CREATE TABLE subledger_bridge_completions(id TEXT PRIMARY KEY,book_id TEXT NOT NULL REFERENCES books(id),firm_id TEXT NOT NULL,company_id TEXT NOT NULL,bridge_id TEXT NOT NULL UNIQUE REFERENCES subledger_period_bridges(id),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE VIEW c01_opening_buckets AS SELECT b.book_id,l.account_id,(SELECT json_group_object(key,value) FROM (SELECT key,value FROM json_each(l.aux_json) ORDER BY key)) AS aux_key,SUM(l.opening_cents) AS cents
 FROM opening_bindings b JOIN opening_lines l ON l.package_version_id=b.package_version_id WHERE b.status='active' GROUP BY b.book_id,l.account_id,(SELECT json_group_object(key,value) FROM (SELECT key,value FROM json_each(l.aux_json) ORDER BY key));
CREATE VIEW c01_formal_buckets AS SELECT book_id,account_id,aux_key,SUM(cents) AS cents FROM (
 SELECT * FROM c01_opening_buckets UNION ALL SELECT v.book_id,l.account_id,(SELECT json_group_object(key,value) FROM (SELECT key,value FROM json_each(l.aux_json) ORDER BY key)),l.debit_cents-l.credit_cents FROM voucher_lines l JOIN vouchers v ON v.id=l.voucher_id) facts GROUP BY book_id,account_id,aux_key;
CREATE VIEW c01_approved_banks AS SELECT b.*,a.ledger_account_id,(SELECT json_group_object(key,value) FROM (SELECT key,value FROM json_each(a.aux_json) ORDER BY key)) AS aux_key FROM bank_identity_bindings b JOIN bank_identity_reviews r ON r.binding_id=b.id AND r.decision='approved' JOIN bank_accounts a ON a.id=b.bank_account_id;
CREATE VIEW c01_item_residuals AS SELECT i.id,i.book_id,i.amount_cents-COALESCE((SELECT SUM(a.amount_cents) FROM subledger_allocations a WHERE a.item_id=i.id AND NOT EXISTS(SELECT 1 FROM subledger_allocation_reversals r WHERE r.allocation_id=a.id)),0) AS cents FROM subledger_items i WHERE i.status IN('open','partial','settled');
CREATE TRIGGER c01_ledger_bank_identities_guard BEFORE INSERT ON ledger_bank_identities BEGIN
 SELECT CASE WHEN (NEW.created_by=accounting_actor_user() AND NEW.firm_id=accounting_actor_firm() AND EXISTS(SELECT 1 FROM service_book_user_permissions WHERE book_id=NEW.book_id AND user_id=accounting_actor_user() AND can_review) AND EXISTS(SELECT 1 FROM books b WHERE b.id=NEW.book_id AND b.company_id=NEW.company_id AND b.firm_id=NEW.firm_id) AND (EXISTS(SELECT 1 FROM ledger_periods p WHERE p.book_id=NEW.book_id AND p.ledger_id=NEW.ledger_id))) IS NOT TRUE THEN RAISE(ABORT,'Reviewed C01 identity or complete exact bridge required') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM internal_period_locks WHERE book_id=NEW.book_id) THEN RAISE(ABORT,'Locked period') END; END;
CREATE TRIGGER c01_ledger_bank_identities_revision AFTER INSERT ON ledger_bank_identities BEGIN INSERT INTO close_dependency_revisions(scope_kind,scope_id,revision) VALUES('book',NEW.book_id,1) ON CONFLICT(scope_kind,scope_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER c01_ledger_bank_identities_update BEFORE UPDATE ON ledger_bank_identities BEGIN SELECT RAISE(ABORT,'C01 bridge facts are immutable'); END;
CREATE TRIGGER c01_ledger_bank_identities_delete BEFORE DELETE ON ledger_bank_identities BEGIN SELECT RAISE(ABORT,'C01 bridge facts are immutable'); END;
CREATE TRIGGER c01_bank_identity_bindings_guard BEFORE INSERT ON bank_identity_bindings BEGIN
 SELECT CASE WHEN (NEW.created_by=accounting_actor_user() AND NEW.firm_id=accounting_actor_firm() AND EXISTS(SELECT 1 FROM service_book_user_permissions WHERE book_id=NEW.book_id AND user_id=accounting_actor_user() AND can_review) AND EXISTS(SELECT 1 FROM books b WHERE b.id=NEW.book_id AND b.company_id=NEW.company_id AND b.firm_id=NEW.firm_id) AND (EXISTS(SELECT 1 FROM ledger_periods p WHERE p.book_id=NEW.book_id AND p.ledger_id=NEW.ledger_id) AND EXISTS(SELECT 1 FROM ledger_bank_identities i JOIN bank_accounts a ON a.id=NEW.bank_account_id WHERE i.id=NEW.stable_bank_id AND i.ledger_id=NEW.ledger_id AND i.company_id=NEW.company_id AND a.book_id=NEW.book_id AND a.active IS TRUE))) IS NOT TRUE THEN RAISE(ABORT,'Reviewed C01 identity or complete exact bridge required') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM internal_period_locks WHERE book_id=NEW.book_id) THEN RAISE(ABORT,'Locked period') END; END;
CREATE TRIGGER c01_bank_identity_bindings_revision AFTER INSERT ON bank_identity_bindings BEGIN INSERT INTO close_dependency_revisions(scope_kind,scope_id,revision) VALUES('book',NEW.book_id,1) ON CONFLICT(scope_kind,scope_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER c01_bank_identity_bindings_update BEFORE UPDATE ON bank_identity_bindings BEGIN SELECT RAISE(ABORT,'C01 bridge facts are immutable'); END;
CREATE TRIGGER c01_bank_identity_bindings_delete BEFORE DELETE ON bank_identity_bindings BEGIN SELECT RAISE(ABORT,'C01 bridge facts are immutable'); END;
CREATE TRIGGER c01_bank_identity_reviews_guard BEFORE INSERT ON bank_identity_reviews BEGIN
 SELECT CASE WHEN (NEW.created_by=accounting_actor_user() AND NEW.firm_id=accounting_actor_firm() AND EXISTS(SELECT 1 FROM service_book_user_permissions WHERE book_id=NEW.book_id AND user_id=accounting_actor_user() AND can_review) AND EXISTS(SELECT 1 FROM books b WHERE b.id=NEW.book_id AND b.company_id=NEW.company_id AND b.firm_id=NEW.firm_id) AND (EXISTS(SELECT 1 FROM bank_identity_bindings b WHERE b.id=NEW.binding_id AND b.book_id=NEW.book_id AND b.created_by<>NEW.created_by
 AND (NEW.decision='rejected' OR NOT EXISTS(SELECT 1 FROM c01_approved_banks other_bank WHERE other_bank.book_id=b.book_id AND (other_bank.bank_account_id=b.bank_account_id OR other_bank.stable_bank_id=b.stable_bank_id)))))) IS NOT TRUE THEN RAISE(ABORT,'Reviewed C01 identity or complete exact bridge required') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM internal_period_locks WHERE book_id=NEW.book_id) THEN RAISE(ABORT,'Locked period') END; END;
CREATE TRIGGER c01_bank_identity_reviews_revision AFTER INSERT ON bank_identity_reviews BEGIN INSERT INTO close_dependency_revisions(scope_kind,scope_id,revision) VALUES('book',NEW.book_id,1) ON CONFLICT(scope_kind,scope_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER c01_bank_identity_reviews_update BEFORE UPDATE ON bank_identity_reviews BEGIN SELECT RAISE(ABORT,'C01 bridge facts are immutable'); END;
CREATE TRIGGER c01_bank_identity_reviews_delete BEFORE DELETE ON bank_identity_reviews BEGIN SELECT RAISE(ABORT,'C01 bridge facts are immutable'); END;
CREATE TRIGGER c01_subledger_period_bridges_guard BEFORE INSERT ON subledger_period_bridges BEGIN
 SELECT CASE WHEN (NEW.created_by=accounting_actor_user() AND NEW.firm_id=accounting_actor_firm() AND EXISTS(SELECT 1 FROM service_book_user_permissions WHERE book_id=NEW.book_id AND user_id=accounting_actor_user() AND can_review) AND EXISTS(SELECT 1 FROM books b WHERE b.id=NEW.book_id AND b.company_id=NEW.company_id AND b.firm_id=NEW.firm_id) AND (EXISTS(SELECT 1 FROM ledger_periods p WHERE p.book_id=NEW.book_id AND p.ledger_id=NEW.ledger_id) AND EXISTS(SELECT 1 FROM service_book_user_permissions WHERE book_id=NEW.source_book_id AND user_id=accounting_actor_user() AND can_review) AND EXISTS(SELECT 1 FROM books s JOIN books t ON t.id=NEW.book_id
 JOIN ledger_periods p ON p.book_id=s.id AND p.ledger_id=NEW.ledger_id
 JOIN internal_period_locks k ON k.id=NEW.source_lock_id AND k.book_id=s.id
 JOIN opening_bindings old_binding ON old_binding.id=NEW.source_binding_id AND old_binding.book_id=s.id AND old_binding.status='active'
 JOIN opening_bindings new_binding ON new_binding.id=NEW.target_binding_id AND new_binding.book_id=t.id AND new_binding.status='active'
 JOIN opening_package_versions opening_version ON opening_version.id=new_binding.package_version_id AND opening_version.status='frozen' AND opening_version.config_fingerprint=new_binding.snapshot_fingerprint
 WHERE s.id=NEW.source_book_id AND s.firm_id=NEW.firm_id AND s.company_id=NEW.company_id AND t.period=strftime('%Y-%m',s.period||'-01','+1 month'))
 AND NOT EXISTS(SELECT 1 FROM vouchers WHERE book_id=NEW.book_id)
 AND NOT EXISTS(SELECT 1 FROM subledger_items WHERE book_id=NEW.book_id)
 AND NOT EXISTS(SELECT 1 FROM (SELECT account_id,aux_key,SUM(cents) AS difference FROM (
 SELECT account_id,aux_key,cents FROM c01_formal_buckets WHERE book_id=NEW.source_book_id UNION ALL
 SELECT account_id,aux_key,-cents FROM c01_opening_buckets WHERE book_id=NEW.book_id) balances GROUP BY account_id,aux_key) differences WHERE difference<>0)
 AND NOT EXISTS(SELECT 1 FROM bank_accounts a WHERE a.book_id IN(NEW.book_id,NEW.source_book_id) AND NOT EXISTS(SELECT 1 FROM c01_approved_banks b WHERE b.bank_account_id=a.id))
 AND NOT EXISTS(SELECT stable_bank_id,ledger_account_id,aux_key FROM c01_approved_banks WHERE book_id=NEW.source_book_id EXCEPT SELECT stable_bank_id,ledger_account_id,aux_key FROM c01_approved_banks WHERE book_id=NEW.book_id)
 AND NOT EXISTS(SELECT stable_bank_id,ledger_account_id,aux_key FROM c01_approved_banks WHERE book_id=NEW.book_id EXCEPT SELECT stable_bank_id,ledger_account_id,aux_key FROM c01_approved_banks WHERE book_id=NEW.source_book_id)
 AND NOT EXISTS(SELECT 1 FROM bank_statement_lines WHERE book_id=NEW.source_book_id AND (bank_account_id IS NULL OR status<>'matched'))
 AND NOT EXISTS(SELECT 1 FROM bank_recon_adjustments a WHERE a.book_id=NEW.source_book_id AND a.amount_cents<>0 AND NOT EXISTS(SELECT 1 FROM bank_adjustment_resolutions r WHERE r.adjustment_id=a.id)))) IS NOT TRUE THEN RAISE(ABORT,'Reviewed C01 identity or complete exact bridge required') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM internal_period_locks WHERE book_id=NEW.book_id) THEN RAISE(ABORT,'Locked period') END; END;
CREATE TRIGGER c01_subledger_period_bridges_revision AFTER INSERT ON subledger_period_bridges BEGIN INSERT INTO close_dependency_revisions(scope_kind,scope_id,revision) VALUES('book',NEW.book_id,1) ON CONFLICT(scope_kind,scope_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER c01_subledger_period_bridges_update BEFORE UPDATE ON subledger_period_bridges BEGIN SELECT RAISE(ABORT,'C01 bridge facts are immutable'); END;
CREATE TRIGGER c01_subledger_period_bridges_delete BEFORE DELETE ON subledger_period_bridges BEGIN SELECT RAISE(ABORT,'C01 bridge facts are immutable'); END;
CREATE TRIGGER c01_subledger_bridge_items_guard BEFORE INSERT ON subledger_bridge_items BEGIN
 SELECT CASE WHEN (NEW.created_by=accounting_actor_user() AND NEW.firm_id=accounting_actor_firm() AND EXISTS(SELECT 1 FROM service_book_user_permissions WHERE book_id=NEW.book_id AND user_id=accounting_actor_user() AND can_review) AND EXISTS(SELECT 1 FROM books b WHERE b.id=NEW.book_id AND b.company_id=NEW.company_id AND b.firm_id=NEW.firm_id) AND (EXISTS(SELECT 1 FROM subledger_period_bridges b JOIN subledger_items s ON s.id=NEW.source_item_id AND s.book_id=b.source_book_id
 JOIN subledger_items t ON t.id=NEW.target_item_id AND t.book_id=b.book_id
 JOIN c01_item_residuals r ON r.id=s.id WHERE b.id=NEW.bridge_id AND b.book_id=NEW.book_id AND b.created_by=NEW.created_by
 AND NEW.remaining_cents=r.cents AND t.amount_cents=r.cents AND t.kind=s.kind AND t.counterparty_id=s.counterparty_id AND t.control_account_id=s.control_account_id
 AND t.control_account_version=s.control_account_version AND t.original_date=s.original_date AND (t.due_date IS s.due_date) AND (SELECT json_group_object(key,value) FROM (SELECT key,value FROM json_each(t.aux_json) ORDER BY key))=(SELECT json_group_object(key,value) FROM (SELECT key,value FROM json_each(s.aux_json) ORDER BY key))
 AND t.source_kind='opening' AND t.source_id=b.id AND t.source_version=1 AND t.created_by=NEW.created_by AND t.status='open'
 AND NOT EXISTS(SELECT 1 FROM subledger_bridge_completions c WHERE c.bridge_id=b.id)))) IS NOT TRUE THEN RAISE(ABORT,'Reviewed C01 identity or complete exact bridge required') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM internal_period_locks WHERE book_id=NEW.book_id) THEN RAISE(ABORT,'Locked period') END; END;
CREATE TRIGGER c01_subledger_bridge_items_revision AFTER INSERT ON subledger_bridge_items BEGIN INSERT INTO close_dependency_revisions(scope_kind,scope_id,revision) VALUES('book',NEW.book_id,1) ON CONFLICT(scope_kind,scope_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER c01_subledger_bridge_items_update BEFORE UPDATE ON subledger_bridge_items BEGIN SELECT RAISE(ABORT,'C01 bridge facts are immutable'); END;
CREATE TRIGGER c01_subledger_bridge_items_delete BEFORE DELETE ON subledger_bridge_items BEGIN SELECT RAISE(ABORT,'C01 bridge facts are immutable'); END;
CREATE TRIGGER c01_subledger_bridge_completions_guard BEFORE INSERT ON subledger_bridge_completions BEGIN
 SELECT CASE WHEN (NEW.created_by=accounting_actor_user() AND NEW.firm_id=accounting_actor_firm() AND EXISTS(SELECT 1 FROM service_book_user_permissions WHERE book_id=NEW.book_id AND user_id=accounting_actor_user() AND can_review) AND EXISTS(SELECT 1 FROM books b WHERE b.id=NEW.book_id AND b.company_id=NEW.company_id AND b.firm_id=NEW.firm_id) AND (EXISTS(SELECT 1 FROM subledger_period_bridges b WHERE b.id=NEW.bridge_id AND b.book_id=NEW.book_id AND b.created_by=NEW.created_by
 AND NOT EXISTS(SELECT 1 FROM c01_item_residuals r WHERE r.book_id=b.source_book_id AND (r.cents<0 OR (r.cents>0 AND NOT EXISTS(SELECT 1 FROM subledger_bridge_items i WHERE i.bridge_id=b.id AND i.source_item_id=r.id AND i.remaining_cents=r.cents))))
 AND (SELECT COUNT(*) FROM subledger_items WHERE book_id=b.book_id)=(SELECT COUNT(*) FROM subledger_bridge_items WHERE bridge_id=b.id)))) IS NOT TRUE THEN RAISE(ABORT,'Reviewed C01 identity or complete exact bridge required') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM internal_period_locks WHERE book_id=NEW.book_id) THEN RAISE(ABORT,'Locked period') END; END;
CREATE TRIGGER c01_subledger_bridge_completions_revision AFTER INSERT ON subledger_bridge_completions BEGIN INSERT INTO close_dependency_revisions(scope_kind,scope_id,revision) VALUES('book',NEW.book_id,1) ON CONFLICT(scope_kind,scope_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER c01_subledger_bridge_completions_update BEFORE UPDATE ON subledger_bridge_completions BEGIN SELECT RAISE(ABORT,'C01 bridge facts are immutable'); END;
CREATE TRIGGER c01_subledger_bridge_completions_delete BEFORE DELETE ON subledger_bridge_completions BEGIN SELECT RAISE(ABORT,'C01 bridge facts are immutable'); END;

DROP TRIGGER c01_exact_bank_statement_lines_insert;
DROP TRIGGER c01_exact_bank_statement_lines_update;
CREATE TRIGGER c01_exact_bank_statement_lines_insert BEFORE INSERT ON bank_statement_lines BEGIN
 SELECT CASE WHEN (EXISTS(SELECT 1 FROM books b WHERE b.id=NEW.book_id AND b.period=NEW.period AND substr(NEW.line_date,1,7)=b.period)
 AND (NEW.bank_account_id IS NULL OR EXISTS(SELECT 1 FROM bank_accounts a WHERE a.id=NEW.bank_account_id AND a.book_id=NEW.book_id))
 AND (NEW.status<>'matched' OR EXISTS(SELECT 1 FROM voucher_lines l JOIN vouchers v ON v.id=l.voucher_id
 WHERE l.id=NEW.matched_voucher_line_id AND v.book_id=NEW.book_id AND l.debit_cents-l.credit_cents=NEW.amount_cents
 AND ((NEW.bank_account_id IS NULL AND (l.code_snapshot LIKE '1001%' OR l.code_snapshot LIKE '1002%')) OR EXISTS(SELECT 1 FROM bank_accounts a WHERE a.id=NEW.bank_account_id AND a.ledger_account_id=l.account_id AND (NOT EXISTS(SELECT key,value FROM json_each(a.aux_json) EXCEPT SELECT key,value FROM json_each(l.aux_json)) AND NOT EXISTS(SELECT key,value FROM json_each(l.aux_json) EXCEPT SELECT key,value FROM json_each(a.aux_json)))))
 AND NOT EXISTS(SELECT 1 FROM bank_statement_lines other_line WHERE other_line.id<>NEW.id AND other_line.matched_voucher_line_id=NEW.matched_voucher_line_id)))) IS NOT TRUE THEN RAISE(ABORT,'C01 fact scope, auxiliary bucket or capacity mismatch') END; END;
CREATE TRIGGER c01_exact_bank_statement_lines_update BEFORE UPDATE ON bank_statement_lines BEGIN
 SELECT CASE WHEN (EXISTS(SELECT 1 FROM books b WHERE b.id=NEW.book_id AND b.period=NEW.period AND substr(NEW.line_date,1,7)=b.period)
 AND (NEW.bank_account_id IS NULL OR EXISTS(SELECT 1 FROM bank_accounts a WHERE a.id=NEW.bank_account_id AND a.book_id=NEW.book_id))
 AND (NEW.status<>'matched' OR EXISTS(SELECT 1 FROM voucher_lines l JOIN vouchers v ON v.id=l.voucher_id
 WHERE l.id=NEW.matched_voucher_line_id AND v.book_id=NEW.book_id AND l.debit_cents-l.credit_cents=NEW.amount_cents
 AND ((NEW.bank_account_id IS NULL AND (l.code_snapshot LIKE '1001%' OR l.code_snapshot LIKE '1002%')) OR EXISTS(SELECT 1 FROM bank_accounts a WHERE a.id=NEW.bank_account_id AND a.ledger_account_id=l.account_id AND (NOT EXISTS(SELECT key,value FROM json_each(a.aux_json) EXCEPT SELECT key,value FROM json_each(l.aux_json)) AND NOT EXISTS(SELECT key,value FROM json_each(l.aux_json) EXCEPT SELECT key,value FROM json_each(a.aux_json)))))
 AND NOT EXISTS(SELECT 1 FROM bank_statement_lines other_line WHERE other_line.id<>NEW.id AND other_line.matched_voucher_line_id=NEW.matched_voucher_line_id)))) IS NOT TRUE THEN RAISE(ABORT,'C01 fact scope, auxiliary bucket or capacity mismatch') END; END;
